import { createHash } from "node:crypto";
import manifest from "@/lib/sat/cfdi40/manifest.json";
import { Cfdi40Error, cfdi40Issue, type Cfdi40IssueCode } from "./errors";

// Fase 5C.5: the official cadena original XSLT and its xsl:include tree, from
// src/lib/sat/cfdi40/cadenaoriginal-xslt.json (generated byte-exact from resources/sat/cfdi40
// by scripts/sat/build-cfdi40-resources.mjs). It is a JSON module, so it is bundled with the
// server code like the official catalogs: no runtime file read, no output file tracing and
// no download. Every text is re-hashed against the manifest before use.

export type Cfdi40XsltBundle = {
  /** Official URL of cadenaoriginal_4_0.xslt (its base URI). */
  readonly rootUrl: string;
  readonly rootSha256: string;
  /** Exact UTF-8 text, a leading BOM included when the SAT file has one. */
  readonly root: string;
  /** Allowlist: official URL → exact text of every versioned include. */
  readonly includes: ReadonlyMap<string, string>;
};
export type Cfdi40XsltBundleSource = {
  root: string;
  resources: readonly {
    url: string;
    name: string;
    sha256: string;
    text: string;
  }[];
};

type ManifestResource = {
  name: string;
  kind: string;
  url: string;
  sha256: string;
  stored: string | false;
};
const satCfd = "http://www.sat.gob.mx/sitio_internet/cfd/";
const issue = (code: Cfdi40IssueCode, name: string) =>
  new Cfdi40Error([cfdi40Issue(code, "XSLT/" + name, "ORBIT")]);
const sha256 = (text: string) =>
  createHash("sha256").update(Buffer.from(text, "utf8")).digest("hex");

/**
 * Checks a bundle against the manifest: the root and every include the manifest lists must
 * be present with the manifest SHA-256, and nothing else may be. Throws
 * SAT_XSLT_RESOURCE_MISSING or SAT_XSLT_RESOURCE_INTEGRITY_FAILED.
 */
export function verifyCfdi40XsltBundle(
  source: Cfdi40XsltBundleSource,
  resources: readonly ManifestResource[] = manifest.resources as ManifestResource[],
): Cfdi40XsltBundle {
  const root = resources.find((r) => r.kind === "XSLT");
  const expected = resources.filter(
    (r) => r.kind === "XSLT" || r.kind === "XSLT_INCLUDE",
  );
  if (!root || source.root !== root.url)
    throw issue("SAT_XSLT_RESOURCE_MISSING", "cadenaoriginal_4_0.xslt");
  const byUrl = new Map(source.resources.map((r) => [r.url, r]));
  for (const entry of source.resources)
    if (!expected.some((e) => e.url === entry.url))
      throw issue("SAT_XSLT_RESOURCE_NOT_ALLOWED", entry.name);
  const includes = new Map<string, string>();
  let rootText = "";
  for (const entry of expected) {
    const found = byUrl.get(entry.url);
    if (!found) throw issue("SAT_XSLT_RESOURCE_MISSING", entry.name);
    if (found.sha256 !== entry.sha256 || sha256(found.text) !== entry.sha256)
      throw issue("SAT_XSLT_RESOURCE_INTEGRITY_FAILED", entry.name);
    if (entry.kind === "XSLT") rootText = found.text;
    else includes.set(entry.url, found.text);
  }
  // Every reference of every stylesheet must be versioned: a missing one fails closed.
  for (const text of [rootText, ...includes.values()])
    for (const [, href] of text.matchAll(
      /<xsl:(?:include|import)\s+href="([^"]+)"/g,
    ))
      if (!includes.has(href))
        throw issue("SAT_XSLT_RESOURCE_MISSING", "xsl:include");
  return Object.freeze({
    rootUrl: root.url,
    rootSha256: root.sha256,
    root: rootText,
    includes,
  });
}

let loaded: Promise<Cfdi40XsltBundle> | undefined;
/** The verified official XSLT bundle, loaded once (lazily, like the large catalogs). */
export function loadCfdi40XsltBundle() {
  return (loaded ??= import("@/lib/sat/cfdi40/cadenaoriginal-xslt.json").then(
    (module) => verifyCfdi40XsltBundle(module.default),
  ));
}

/**
 * The text an xsl:include/xsl:import may load: only an absolute official SAT URL that the
 * versioned bundle allowlists, exactly as written. Relative or normalized-away paths (..),
 * other schemes (file:, https: to elsewhere, data:), hosts, ports, queries or fragments are
 * refused with SAT_XSLT_RESOURCE_NOT_ALLOWED, so nothing is ever read from disk or network.
 */
export function resolveSatXsltInclude(
  bundle: Cfdi40XsltBundle,
  href: string,
): string {
  let url: URL | null = null;
  try {
    url = new URL(href);
  } catch {
    url = null;
  }
  const allowed =
    url !== null &&
    url.href === href &&
    url.protocol === "http:" &&
    url.host === "www.sat.gob.mx" &&
    !url.search &&
    !url.hash &&
    href.startsWith(satCfd) &&
    !href.split("/").includes("..");
  const text = allowed ? bundle.includes.get(href) : undefined;
  if (text === undefined)
    throw issue("SAT_XSLT_RESOURCE_NOT_ALLOWED", "xsl:include");
  return text;
}
